impl ViewShortcut {
    fn key(self) -> &'static str {
        match self {
            Self::Follow => "f",
            Self::Timestamps => "t",
            Self::Sms => "s",
            Self::Join => "j",
            Self::Karaoke => "k",
            Self::Confidence => "c",
        }
    }
}

