/// Strip the light Markdown the notices file uses. The wording itself is kept
/// verbatim; only the emphasis markers and bullet prefix are removed.
fn markdown_plain(line: &str) -> String {
    line.replace("**", "").replace('`', "")
}

/// Split a notices line into prose and the http(s) addresses inside it.
fn split_urls(line: &str) -> (String, Vec<String>) {
    let mut prose = String::new();
    let mut urls = Vec::new();
    let mut rest = line;
    while let Some(start) = [rest.find("http://"), rest.find("https://")]
        .into_iter()
        .flatten()
        .min()
    {
        prose.push_str(&rest[..start]);
        let after = &rest[start..];
        let end = after
            .find(|c: char| c.is_whitespace())
            .unwrap_or(after.len());
        let url = after[..end].trim_end_matches([',', ';', '.']).to_string();
        if !url.is_empty() {
            urls.push(url);
        }
        rest = &after[end..];
    }
    prose.push_str(rest);
    let prose = prose
        .replace(" ,", ",")
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .replace(", ,", ",");
    (
        prose
            .trim_end_matches([' ', ',', '\u{2014}', ':'])
            .to_string(),
        urls,
    )
}

fn licence_entry(raw: &str, bullet: bool, scheme: Scheme) -> Element<'static, Message> {
    let (prose, urls) = split_urls(raw);
    let prose = markdown_plain(&prose);
    let mut entry = column![].spacing(theme::SPACE_XS).width(Length::Fill);
    if !prose.is_empty() {
        let mut line = row![]
            .spacing(theme::SPACE_MD)
            .align_y(iced::Alignment::Start);
        if bullet {
            line = line.push(text("\u{2022}").size(theme::TEXT_SM).color(scheme.muted));
        }
        line = line.push(
            text(prose)
                .size(theme::TEXT_SM)
                .wrapping(iced::widget::text::Wrapping::WordOrGlyph)
                .width(Length::Fill)
                .color(scheme.text),
        );
        entry = entry.push(line);
    }
    for url in urls {
        entry = entry.push(container(link_button(url.clone(), url, scheme)).padding(
            iced::Padding {
                top: 0.0,
                right: 0.0,
                bottom: 0.0,
                left: if bullet { 18.0 } else { 0.0 },
            },
        ));
    }
    entry.into()
}

fn licences_page(scheme: Scheme) -> Element<'static, Message> {
    let lines: Vec<&str> = LICENSES_TEXT.lines().collect();
    let mut page = column![].spacing(theme::SPACE_MD).width(Length::Fill);
    let mut index = 0;
    while index < lines.len() {
        let line = lines[index].trim_end();
        if line.is_empty() {
            index += 1;
            continue;
        }
        if line.starts_with("# ") {
            index += 1;
            continue;
        }
        if let Some(heading) = line.strip_prefix("## ") {
            page = page.push(
                container(report_section(heading, scheme)).padding(iced::Padding {
                    top: theme::SPACE_MD,
                    right: 0.0,
                    bottom: 0.0,
                    left: 0.0,
                }),
            );
            index += 1;
            continue;
        }
        let bullet = line.starts_with("- ");
        let mut parts = vec![line.trim_start_matches("- ").to_string()];
        index += 1;
        while index < lines.len() {
            let next = lines[index].trim_end();
            if next.is_empty() || next.starts_with("- ") || next.starts_with('#') {
                break;
            }
            parts.push(next.trim().to_string());
            index += 1;
        }
        page = page.push(licence_entry(&parts.join(" "), bullet, scheme));
    }
    page.into()
}

/// Layer `dialog` over `base` behind a dimming backdrop that swallows pointer
/// input, so a visible modal blocks everything outside it. The backdrop covers
/// the whole window and takes the cursor for itself, so the widgets underneath
/// never see a hover or a click.
fn modal_overlay<'a>(
    base: impl Into<Element<'a, Message>>,
    dialog: impl Into<Element<'a, Message>>,
    scheme: Scheme,
    dismiss: Option<Message>,
) -> Element<'a, Message> {
    let base = base.into();
    let dialog = dialog.into();
    let on_scrim = dismiss.clone().unwrap_or(Message::Noop);
    let backdrop = mouse_area(
        container(horizontal_space())
            .width(Length::Fill)
            .height(Length::Fill)
            .style(move |_theme| container::Style {
                background: Some(scheme.scrim.into()),
                ..container::Style::default()
            }),
    )
    // `Idle` keeps the arrow cursor over the scrim instead of inheriting the
    // text or pointer cursor of whatever sits underneath.
    .interaction(mouse::Interaction::Idle)
    .on_press(on_scrim.clone())
    .on_right_press(on_scrim)
    .on_middle_press(Message::Noop)
    // The stack already withholds the wheel from layers under an area that
    // reports an interaction, but capturing it here says so outright: a
    // scrollable behind the scrim must never move.
    .on_scroll(|_| Message::Noop);
    // The dialog itself also consumes stray clicks and keeps an arrow cursor
    // on its non-interactive areas, so nothing behind it is clickable.
    let dialog = mouse_area(dialog)
        .interaction(mouse::Interaction::Idle)
        .on_press(Message::Noop)
        .on_right_press(Message::Noop)
        .on_middle_press(Message::Noop)
        .on_scroll(|_| Message::Noop);
    let centered = container(dialog)
        .center(Length::Fill)
        .width(Length::Fill)
        .height(Length::Fill);
    stack![base, backdrop, centered].into()
}

/// Unix seconds from a file's modification time, if it can be read.
fn file_unix_secs(path: &Path) -> Option<u64> {
    std::fs::metadata(path)
        .ok()?
        .modified()
        .ok()?
        .duration_since(std::time::UNIX_EPOCH)
        .ok()
        .map(|duration| duration.as_secs())
}

fn unix_secs() -> u64 {
    SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|duration| duration.as_secs())
        .unwrap_or(0)
}

/// One filesystem pass over the history: which transcripts still exist. The
/// result is cached on [`App`] so a list build never touches the disk.
fn recent_presence_of(recent: &[RecentEntry]) -> Vec<bool> {
    recent
        .iter()
        .map(|entry| {
            entry
                .transcript
                .as_deref()
                .is_some_and(|path| path.is_file())
        })
        .collect()
}

/// Parallel cache of which history entries still have their audio on disk.
fn recent_audio_presence_of(recent: &[RecentEntry]) -> Vec<bool> {
    recent
        .iter()
        .map(|entry| entry.audio.as_deref().is_some_and(|path| path.is_file()))
        .collect()
}

/// The file a history row is named for: its audio, or the transcript when the
/// audio is gone.

/// Per-speaker time, share of the spoken total, line and word counts. A line
/// without an end borrows the next line's start, so the shares add up.
fn speaker_stats(lines: &[DocLine], duration: Option<f32>) -> Vec<SpeakerStat> {
    let mut stats: Vec<SpeakerStat> = Vec::new();
    for (index, line) in lines.iter().enumerate() {
        let Some(start) = line.start else {
            continue;
        };
        let end = lines
            .iter()
            .skip(index + 1)
            .find_map(|next| next.start)
            .or(duration)
            .unwrap_or(start)
            .max(start);
        let seconds = end - start;
        let name = line.speaker.trim();
        let name = if name.is_empty() {
            "Unattributed".to_string()
        } else {
            name.to_string()
        };
        let words = line_text(line).split_whitespace().count();
        match stats.iter_mut().find(|stat| stat.name == name) {
            Some(stat) => {
                stat.seconds += seconds;
                stat.lines += 1;
                stat.words += words;
            }
            None => stats.push(SpeakerStat {
                name,
                seconds,
                share: 0.0,
                lines: 1,
                words,
            }),
        }
    }
    let total: f32 = stats.iter().map(|stat| stat.seconds).sum();
    for stat in &mut stats {
        stat.share = if total > 0.0 {
            stat.seconds / total
        } else {
            0.0
        };
    }
    stats.sort_by(|a, b| {
        b.seconds
            .partial_cmp(&a.seconds)
            .unwrap_or(std::cmp::Ordering::Equal)
    });
    stats
}

/// One transcript paragraph: a timestamp when asked for, the speaker, then the
/// spoken text.
fn report_line(speaker: &str, start: Option<f32>, text: &str, timestamps: bool) -> String {
    let stamp = if timestamps {
        start
            .map(|seconds| format!("{} ", format_timestamp(seconds as f64)))
            .unwrap_or_default()
    } else {
        String::new()
    };
    let speaker = if speaker.trim().is_empty() {
        "Unattributed"
    } else {
        speaker.trim()
    };
    format!("{stamp}{speaker}: {text}")
}

/// The report as styled blocks: title and provenance, then the participants,
/// the summary and the transcript the options ask for.
fn report_blocks(content: &ReportContent<'_>) -> Vec<ReportBlock> {
    let mut blocks = vec![ReportBlock::Title(content.title.to_string())];
    let length = content
        .duration
        .map(|seconds| format!(" \u{00b7} {}", format_secs(seconds as f64)))
        .unwrap_or_default();
    blocks.push(ReportBlock::Meta(format!(
        "Generated {}{length}",
        content.generated
    )));

    if content.participants {
        let stats = speaker_stats(content.lines, content.duration);
        if !stats.is_empty() {
            blocks.push(ReportBlock::Heading("Participants".to_string()));
            for stat in &stats {
                blocks.push(ReportBlock::Bullet(format!(
                    "{} \u{2014} {} speaking ({:.0}%), {} {}, {} {}",
                    stat.name,
                    format_secs(stat.seconds as f64),
                    stat.share * 100.0,
                    stat.lines,
                    if stat.lines == 1 { "turn" } else { "turns" },
                    stat.words,
                    if stat.words == 1 { "word" } else { "words" }
                )));
            }
        }
    }

    if let Some((briefing, lines)) = content.summary {
        blocks.push(ReportBlock::Heading("Summary".to_string()));
        if !briefing.overview.trim().is_empty() {
            blocks.push(ReportBlock::Paragraph(
                briefing.overview.trim().to_string(),
            ));
        }
        for item in &briefing.points {
            let cite = hippo_briefing::citation(item, lines)
                .map(|range| format!(" ({range})"))
                .unwrap_or_default();
            blocks.push(ReportBlock::Bullet(format!(
                "{}{cite}",
                item.text.trim()
            )));
        }
    }

    if !content.lines.is_empty() {
        blocks.push(ReportBlock::Heading("Transcript".to_string()));
        if content.merge_lines {
            let mut current: Option<(String, Option<f32>, Vec<String>)> = None;
            let flush = |blocks: &mut Vec<ReportBlock>,
                             speaker: String,
                             start: Option<f32>,
                             texts: Vec<String>| {
                blocks.push(ReportBlock::Paragraph(report_line(
                    &speaker,
                    start,
                    &texts.join(" "),
                    content.timestamps,
                )));
            };
            for line in content.lines {
                let speaker = if line.speaker.trim().is_empty() {
                    "Unattributed".to_string()
                } else {
                    line.speaker.trim().to_string()
                };
                let text = line_text(line);
                match current.as_mut() {
                    Some((who, _, texts)) if *who == speaker => texts.push(text),
                    _ => {
                        if let Some((who, start, texts)) = current.take() {
                            flush(&mut blocks, who, start, texts);
                        }
                        current = Some((speaker, line.start, vec![text]));
                    }
                }
            }
            if let Some((who, start, texts)) = current {
                flush(&mut blocks, who, start, texts);
            }
        } else {
            for line in content.lines {
                blocks.push(ReportBlock::Paragraph(report_line(
                    &line.speaker,
                    line.start,
                    &line_text(line),
                    content.timestamps,
                )));
            }
        }
    }

    blocks
}

fn briefing_text(briefing: &Briefing, lines: &[BriefingLine]) -> String {
    let mut out = String::new();
    if !briefing.overview.trim().is_empty() {
        out.push_str(briefing.overview.trim());
        out.push_str("\n\n");
    }
    if !briefing.points.is_empty() {
        out.push_str("Key points\n\n");
        for item in &briefing.points {
            out.push_str("- ");
            out.push_str(item.text.trim());
            if let Some(range) = hippo_briefing::citation(item, lines) {
                out.push_str(&format!(" ({range})"));
            }
            out.push('\n');
        }
    }
    out
}

/// One cue per key point, timed by the lines it cites, so the timed formats
/// describe the briefing rather than a transcript it never was.
fn briefing_cues(briefing: &Briefing, lines: &[BriefingLine]) -> (Vec<Cue>, Option<f32>) {
    let mut cues = Vec::new();
    for item in &briefing.points {
        let first = item
            .lines
            .first()
            .and_then(|number| number.checked_sub(1))
            .and_then(|index| lines.get(index));
        let last = item
            .lines
            .last()
            .and_then(|number| number.checked_sub(1))
            .and_then(|index| lines.get(index))
            .or(first);
        let Some(start) = first.map(|line| line.start) else {
            continue;
        };
        cues.push(Cue {
            start: Some(start),
            end: last.and_then(|line| line.end).filter(|end| *end >= start),
            speaker: String::new(),
            text: item.text.trim().to_string(),
            words: Vec::new(),
        });
    }
    let duration = lines
        .iter()
        .map(|line| line.end.unwrap_or(line.start))
        .reduce(f32::max);
    (cues, duration)
}

fn recent_title(entry: &RecentEntry) -> String {
    entry
        .name
        .as_deref()
        .map(str::trim)
        .filter(|name| !name.is_empty())
        .map(str::to_string)
        .unwrap_or_else(|| recent_file_name(entry))
}

/// The row's file name, whatever the row is called in the lists. Matching
/// against a run's record must use this, not the display name.
fn recent_file_name(entry: &RecentEntry) -> String {
    entry
        .audio
        .as_deref()
        .or(entry.transcript.as_deref())
        .and_then(|path| path.file_name())
        .map(|name| name.to_string_lossy().into_owned())
        .unwrap_or_else(|| "Untitled".to_string())
}

/// Folder that holds a history row's output, for Reveal.
fn recent_reveal_dir(entry: &RecentEntry) -> Option<PathBuf> {
    entry
        .transcript
        .as_deref()
        .or(entry.audio.as_deref())
        .and_then(|path| path.parent())
        .filter(|parent| !parent.as_os_str().is_empty())
        .map(Path::to_path_buf)
}

/// The compact action at the right end of a recent tab's footer. `message` is
/// `None` whenever the action is disabled; `tooltip` says why.
#[derive(Debug, Clone)]
struct FooterAction {
    label: &'static str,
    message: Option<Message>,
    tooltip: &'static str,
}

/// A day heading above a run of history rows.
fn day_header(day: &str, scheme: &Scheme) -> Element<'static, Message> {
    let scheme = *scheme;
    container(
        text(day.to_string())
            .size(11)
            .color(scheme.muted),
    )
    .padding(iced::Padding {
        top: 8.0,
        right: 2.0,
        bottom: 2.0,
        left: 2.0,
    })
    .width(Length::Fill)
    .into()
}

/// Distinct speaker names in a turn list, clamped to the `u8` the history
/// stores. `None` when there are no turns to count.
fn distinct_speaker_count(turns: &[backend::Turn]) -> Option<u8> {
    if turns.is_empty() {
        return None;
    }
    let mut names: Vec<&str> = Vec::new();
    for turn in turns {
        let name = turn.speaker.as_str();
        if !names.contains(&name) {
            names.push(name);
        }
    }
    Some(names.len().clamp(1, u8::MAX as usize) as u8)
}

/// One line for a history row: duration, speaker count and the finish time.
/// A row whose transcript is gone says so instead, in the danger colour.
/// Human label for a preset argument, e.g. `accuracy` -> `Accuracy`.
fn preset_label(preset: &str) -> String {
    Preset::from_arg(preset)
        .map(|preset| preset.label().to_string())
        .unwrap_or_else(|| preset.to_string())
}

/// Duration followed by the preset that produced a transcript.
fn recent_detail_text(entry: &RecentEntry) -> String {
    let mut parts = Vec::new();
    if let Some(duration) = entry.duration {
        parts.push(format_secs(duration));
    }
    if let Some(preset) = entry.preset.as_deref().map(preset_label) {
        parts.push(preset);
    }
    parts.join(" \u{00b7} ")
}

/// Human label for a language code. Unknown codes are uppercased.
fn language_label(code: &str) -> String {
    if code.is_empty() || code.eq_ignore_ascii_case("auto") {
        return String::new();
    }
    let option = LanguageOpt::from_code(Some(code));
    if option == LanguageOpt::Auto {
        code.to_uppercase()
    } else {
        option.label().to_string()
    }
}

/// Whether the transcript differs from its pre-edit copy. Used when the
/// manifest's flag needs recomputing, not per frame.
fn transcript_differs_from_original(transcript: &Path) -> bool {
    let original = crate::files::unedited_path(transcript);
    match (std::fs::read(transcript), std::fs::read(&original)) {
        (Ok(current), Ok(original)) => current != original,
        _ => false,
    }
}

/// A day heading for the history list: "Today", "Yesterday" or "Nov 3".
fn day_heading(finished_at: u64, now: u64) -> String {
    let Some(when) = local_datetime(finished_at) else {
        return "Earlier".to_string();
    };
    let Some(current) = local_datetime(now) else {
        return "Earlier".to_string();
    };
    match current.date().to_julian_day() - when.date().to_julian_day() {
        0 => "Today".to_string(),
        1 => "Yesterday".to_string(),
        _ => format!("{} {}", month_short(when.month()), when.day()),
    }
}

/// Wall-clock time in the local zone, e.g. "14:05".
fn clock_time(unix: u64) -> String {
    match local_datetime(unix) {
        Some(when) => format!("{:02}:{:02}", when.hour(), when.minute()),
        None => "--:--".to_string(),
    }
}

/// A full local date and time, e.g. "Nov 8 2026, 14:05".
fn full_datetime(unix: u64) -> String {
    match local_datetime(unix) {
        Some(when) => format!(
            "{} {} {}, {:02}:{:02}",
            month_short(when.month()),
            when.day(),
            when.year(),
            when.hour(),
            when.minute()
        ),
        None => "Unknown".to_string(),
    }
}

fn local_datetime(unix: u64) -> Option<time::OffsetDateTime> {
    let utc = time::OffsetDateTime::from_unix_timestamp(unix as i64).ok()?;
    Some(utc.to_offset(local_offset()))
}

fn local_offset() -> time::UtcOffset {
    time::UtcOffset::current_local_offset().unwrap_or(time::UtcOffset::UTC)
}

fn month_short(month: time::Month) -> &'static str {
    use time::Month::*;
    match month {
        January => "Jan",
        February => "Feb",
        March => "Mar",
        April => "Apr",
        May => "May",
        June => "Jun",
        July => "Jul",
        August => "Aug",
        September => "Sep",
        October => "Oct",
        November => "Nov",
        December => "Dec",
    }
}

/// Insert or replace a history entry, newest first. Identity is the audio path
/// when there is one, otherwise the transcript path, so re-running the same
/// source replaces its entry instead of adding a second row. Returns its index.
/// Messages the File panel's context menu can send. Choosing any of them
/// closes the menu before it runs.
fn closes_row_menu(message: &Message) -> bool {
    matches!(
        message,
        Message::OpenRecent(_)
            | Message::RemoveRecent(_)
            | Message::RevealRecent(_)
            | Message::RevealRecentAudio(_)
            | Message::RevealQueueAudio(_)
            | Message::ToggleFavorite(_)
            | Message::CopyRecentText(_)
            | Message::RetranscribeRecent(_)
            | Message::EnqueueRecent(_)
            | Message::ExportRecentAs(_, _)
            | Message::TranscribeQueueItem(_)
            | Message::OpenQueueRow(_)
            | Message::OpenInfo(_, _)
            | Message::RemoveItem(_)
            | Message::RetryItem(_)
            | Message::RetryRecording(_)
            | Message::SkipItem(_)
            | Message::AddFiles
            | Message::AddFolder
            | Message::ClearQueue
            | Message::RequestClearHistory
            | Message::OpenVersions(_, _)
            | Message::OpenLabels(_, _)
            | Message::ImportVersions
            | Message::ScanOrphans
    )
}

/// Stable identity for the Favorites order: the audio path, or the transcript
/// path for a history entry whose audio is gone. The same key survives a
/// re-transcription, which replaces the files but keeps the audio name.
fn favorite_key(entry: &RecentEntry) -> Option<String> {
    entry
        .audio
        .as_deref()
        .or(entry.transcript.as_deref())
        .map(|path| path.display().to_string())
}

fn merge_recent_entry(recent: &mut Vec<RecentEntry>, mut entry: RecentEntry) -> usize {
    let existing = entry
        .audio
        .as_deref()
        .and_then(|audio| {
            recent
                .iter()
                .position(|other| other.audio.as_deref() == Some(audio))
        })
        .or_else(|| {
            if entry.audio.is_none() {
                entry.transcript.as_ref().and_then(|transcript| {
                    recent.iter().position(|other| {
                        other.audio.is_none() && other.transcript.as_ref() == Some(transcript)
                    })
                })
            } else {
                None
            }
        });
    // The row's identity, captured before the sort moves rows: a position
    // taken now would name a different entry once newest-first ordering has
    // run, and every caller treats the return value as the entry's slot.
    let identity = (
        entry.audio.clone(),
        entry.transcript.clone(),
        entry.finished_at,
    );
    match existing {
        Some(index) => {
            // A rerun replaces the output but must not clear the user's
            // favorite, nor forget that the item came from the recorder.
            entry.favorite |= recent[index].favorite;
            entry.recording |= recent[index].recording;
            recent[index] = entry;
        }
        None => recent.push(entry),
    }
    // Newest first; ties fall back to the path so the order is stable.
    recent.sort_by(|a, b| {
        b.finished_at.cmp(&a.finished_at).then_with(|| {
            (a.transcript.as_deref(), a.audio.as_deref())
                .cmp(&(b.transcript.as_deref(), b.audio.as_deref()))
        })
    });
    recent
        .iter()
        .position(|other| {
            other.audio == identity.0
                && other.transcript == identity.1
                && other.finished_at == identity.2
        })
        .unwrap_or(0)
}

fn queue_weight(item: &QueueItem, fallback: f32) -> f32 {
    item.duration
        .map(|duration| duration as f32)
        .filter(|duration| *duration > 0.0)
        .unwrap_or(fallback)
}

/// Coarse "time left" text: the throughput is only good to about this
/// resolution, so finer digits would be false precision.
fn eta_bucket(left: f32) -> String {
    if left >= 600.0 {
        let minutes = ((left / 60.0) / 5.0).round().max(1.0) * 5.0;
        format!("{minutes:.0} min")
    } else if left >= 60.0 {
        let seconds = ((left / 5.0).round() * 5.0).max(5.0);
        format_secs(seconds as f64)
    } else {
        let seconds = ((left / 5.0).round() * 5.0).max(5.0);
        format!("{seconds:.0} s")
    }
}

/// Median of an already-sorted slice.
fn median(sorted: &[f32]) -> f32 {
    let mid = sorted.len() / 2;
    if sorted.len() % 2 == 0 {
        (sorted[mid - 1] + sorted[mid]) * 0.5
    } else {
        sorted[mid]
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum ToastTone {
    Success,
    Info,
    Danger,
}

fn toast_tone(message: &str) -> ToastTone {
    let message = message.to_ascii_lowercase();
    if [
        "fail",
        "error",
        "could not",
        "cannot",
        "missing",
        "unavailable",
        "disabled",
        "read-only",
        "too short",
        "no audio",
        "no output",
    ]
    .iter()
    .any(|needle| message.contains(needle))
    {
        ToastTone::Danger
    } else if [
        "pro",
        "download",
        "copied",
        "imported",
        "queued",
        "stopping",
        "purchase",
        "trial",
        "restored",
        "switched",
        "player is",
        "editing is",
        "reviewing",
    ]
    .iter()
    .any(|needle| message.contains(needle))
    {
        ToastTone::Info
    } else {
        ToastTone::Success
    }
}

fn toast_ttl(message: &str) -> Duration {
    match toast_tone(message) {
        ToastTone::Danger => Duration::from_secs(6),
        ToastTone::Info => Duration::from_secs(3),
        ToastTone::Success => Duration::from_millis(2400),
    }
}

/// An add's final summary: "N items restored, M items queued". A zero clause is
/// dropped entirely rather than printed as "0 items", and an empty summary is
/// returned when nothing landed at all.
fn add_summary(restored: usize, queued: usize) -> String {
    let clause = |count: usize, verb: &str| {
        format!(
            "{count} item{} {verb}",
            if count == 1 { "" } else { "s" }
        )
    };
    match (restored, queued) {
        (0, 0) => String::new(),
        (0, queued) => clause(queued, "queued"),
        (restored, 0) => clause(restored, "restored"),
        (restored, queued) => format!(
            "{}, {}",
            clause(restored, "restored"),
            clause(queued, "queued")
        ),
    }
}

/// Label to render verbatim while decoding, or `None` for the plain
/// "Decoding" placeholder whose animated dots are drawn instead.
fn decoding_label(stage: &str, label: &str) -> Option<String> {
    let stage = stage.trim();
    let lower = stage.to_ascii_lowercase();
    if !lower.starts_with("decoding") {
        return None;
    }
    // A bare "Decoding" keeps the animation; "Decoding 42%" carries detail.
    if lower.len() == "decoding".len() {
        return None;
    }
    Some(label.to_string())
}

/// Progress-bar text: phase (with detail) plus overall percentage.
fn progress_label(
    status: &Status,
    stage: &str,
    progress: f32,
    has_queue: bool,
    dots: usize,
    file: Option<&str>,
) -> String {
    let mut label = match status {
        Status::Idle if has_queue => "Ready".to_string(),
        Status::Idle => "Idle".to_string(),
        Status::Error(message) => format!("Error: {message}"),
        _ => {
            let label = capitalize_first(stage);
            let lower = label.to_ascii_lowercase();
            // Animate ellipses while decoding (1..=5, cycling).
            if lower == "decoding" {
                format!("{label}{}", ".".repeat(dots.clamp(1, 5)))
            } else if lower == "done" {
                // Keep saying "Transcribing" while the eased bar catches up;
                // only call the run completed once the bar has reached 100%.
                if matches!(status, Status::Done) && progress >= 0.995 {
                    format!("Completed ({:.0}%)", progress.clamp(0.0, 1.0) * 100.0)
                } else {
                    format!("Transcribing ({:.0}%)", progress.clamp(0.0, 1.0) * 100.0)
                }
            } else if lower.starts_with("transcribing") {
                format!("{label} ({:.0}%)", progress.clamp(0.0, 1.0) * 100.0)
            } else {
                label
            }
        }
    };
    if let Some(file) = file {
        label = format!("{file} \u{2014} {label}");
    }
    label
}

