    #[test]
    fn clear_history_asks_first_then_drops_finished_items_and_keeps_the_queue() {
        let _guard = env_lock();
        let _config = ConfigEnv::new("clear-history");
        let mut app = pro_app();
        app.recent.push(RecentEntry {
            audio: Some(PathBuf::from("/media/talk.mp3")),
            transcript: Some(PathBuf::from("/media/talk.txt")),
            finished_at: 5,
            favorite: true,
            ..Default::default()
        });
        app.favorite_order.push("/media/talk.mp3".to_string());
        app.queue.push(queue_item(PathBuf::from("/media/next.mp3")));

        // The action opens a confirmation and changes nothing yet.
        let _ = app.update(Message::RequestClearHistory);
        assert!(app.clear_confirm, "Clear history should ask first");
        assert_eq!(app.recent.len(), 1, "the request must not clear anything");

        // Backing out keeps every row.
        let _ = app.update(Message::CloseClearHistory);
        assert!(!app.clear_confirm);
        assert_eq!(app.recent.len(), 1);

        let _ = app.update(Message::RequestClearHistory);
        let _ = app.update(Message::ConfirmClearHistory);

        assert!(!app.clear_confirm);
        assert!(app.recent.is_empty());
        assert!(app.favorite_order.is_empty());
        assert_eq!(app.queue.len(), 1, "queue work is not history");
        // The cleared list is persisted, not just dropped in memory.
        let (_, _, recent, favorites) = App::load_queue_and_batch();
        assert!(recent.is_empty());
        assert!(favorites.is_empty());
    }

    #[test]
    fn renaming_a_history_row_changes_its_title_only() {
        let _guard = env_lock();
        let _config = ConfigEnv::new("rename-row");
        let media = temp_dir("rename-row-media");
        let audio = media.join("talk.mp3");
        std::fs::write(&audio, b"audio").unwrap();
        let transcript = media.join("talk.txt");
        std::fs::write(&transcript, "[00:00] SPEAKER 1: hi\n").unwrap();

        let mut app = pro_app();
        push_recent(
            &mut app,
            Some(audio.clone()),
            transcript.clone(),
            Some(10.0),
            Vec::new(),
        );
        assert_eq!(recent_title(&app.recent[0]), "talk.mp3");

        let _ = app.update(Message::OpenRenameRecent(0));
        let state = app
            .rename_recent
            .as_ref()
            .expect("the rename form should open");
        assert_eq!(state.text, "talk.mp3", "the field starts on the shown name");

        let _ = app.update(Message::RenameRecentChanged("Board meeting".to_string()));
        let _ = app.update(Message::RenameRecentSave);
        assert!(app.rename_recent.is_none());
        assert_eq!(recent_title(&app.recent[0]), "Board meeting");
        assert_eq!(
            app.recent[0].audio.as_deref(),
            Some(audio.as_path()),
            "the file is not renamed"
        );
        assert!(audio.is_file() && transcript.is_file());

        // The alias is persisted with the index.
        let (_, _, recent, _) = App::load_queue_and_batch();
        let stored = recent
            .iter()
            .find(|entry| entry.name.is_some())
            .expect("the name was not stored");
        assert_eq!(stored.name.as_deref(), Some("Board meeting"));

        // Typing the file's own name drops the alias rather than pinning one.
        let _ = app.update(Message::OpenRenameRecent(0));
        let _ = app.update(Message::RenameRecentChanged("talk.mp3".to_string()));
        let _ = app.update(Message::RenameRecentSave);
        assert_eq!(app.recent[0].name, None);
        assert_eq!(recent_title(&app.recent[0]), "talk.mp3");

        let _ = std::fs::remove_dir_all(&media);
    }

    #[test]
    fn a_selected_queued_file_never_shows_the_last_transcript() {
        let _guard = env_lock();
        let _config = ConfigEnv::new("queue-notice");
        let original = "[00:00] SPEAKER 1: old words\n";
        let (mut app, _transcript, media) = line_edit_fixture("queue-notice", original);
        // A finished transcript is on screen; the queue holds an untranscribed
        // file the user is about to focus.
        assert!(app.selected_view.is_some());
        let queued = media.join("next.mp3");
        std::fs::write(&queued, b"audio").unwrap();
        app.queue.push(queue_item(queued));

        let _ = app.update(Message::SelectTab(PaneTab::Queue));
        assert_eq!(app.selected, Some(0));

        let (title, body) = app
            .transcript_notice()
            .expect("the pane should describe the queue row");
        assert_eq!(title, "Not transcribed yet");
        assert!(body.contains("Run the queue"), "{body}");
        assert_eq!(app.shown_item_title(), "next.mp3");
        // The old document is still loaded behind the notice, so the guard is
        // what keeps its text off the pane.
        assert!(app.shown_transcript().contains("old words"));

        // A failed row explains itself instead of promising a transcript.
        app.queue[0].status = ItemStatus::Failed("no speech found".to_string());
        let (title, body) = app
            .transcript_notice()
            .expect("a failed row still describes itself");
        assert_eq!(title, "Not transcribed");
        assert!(body.contains("no speech found"), "{body}");

        let _ = std::fs::remove_dir_all(&media);
    }

