    /// Every dialog, so a variant added to `Modal` cannot go untested: the
    /// escape and render passes below each walk this list.
    const ALL_MODALS: [Modal; 14] = [
        Modal::ClearHistory,
        Modal::Summary,
        Modal::DeleteLine,
        Modal::Calibration,
        Modal::Paywall,
        Modal::Settings,
        Modal::Help,
        Modal::RunSetup,
        Modal::Rename,
        Modal::Info,
        Modal::Versions,
        Modal::Labels,
        Modal::RenameRecent,
        Modal::Report,
    ];

    /// Raise one dialog the way the app would.
    fn raise_modal(app: &mut App, modal: Modal) {
        match modal {
            Modal::ClearHistory => app.clear_confirm = true,
            Modal::Summary => app.summary_open = true,
            Modal::DeleteLine => {
                // The confirmation previews the line being edited, so it needs
                // an editor to preview.
                let _ = app.update(Message::EditLine(1));
                app.delete_confirm = true;
            }
            Modal::Calibration => {
                app.calibration = Some(Calibration::new(Preset::Accuracy, false))
            }
            Modal::Paywall => app.paywall_open = true,
            Modal::Settings => app.settings_open = true,
            Modal::Help => app.help_open = Some(HelpKind::About),
            Modal::RunSetup => app.run_setup_open = true,
            Modal::Rename => app.rename_open = true,
            Modal::Vocabulary => {
                let _ = app.open_vocabulary();
            }
            Modal::Briefing => app.briefing = Some(BriefingState::NeedsModel),
            Modal::Info => {
                app.recent.push(RecentEntry {
                    audio: Some(PathBuf::from("/media/talk.mp3")),
                    transcript: Some(PathBuf::from("/media/talk.txt")),
                    finished_at: 5,
                    ..Default::default()
                });
                let index = app.recent.len() - 1;
                app.info_open = app.capture_file_info(PaneTab::History, index);
            }
            Modal::Versions => {
                let dir = std::env::temp_dir().join(format!(
                    "hippo-modal-versions-{}",
                    std::process::id()
                ));
                let _ = std::fs::create_dir_all(&dir);
                let audio = dir.join("talk.mp3");
                std::fs::write(&audio, b"audio").unwrap();
                let transcript = dir.join("talk-ts.txt");
                std::fs::write(&transcript, "[00:00] A: hi\n").unwrap();
                let manifest = serde_json::json!({
                    "schema_version": 1,
                    "asset": { "id": "a1", "audio": "talk.mp3" },
                    "current": "v1",
                    "versions": [{
                        "id": "v1",
                        "settings_key": "key-1",
                        "preset": "accuracy",
                        "created_at": 1,
                        "transcript": "talk-ts.txt",
                        "plain": "talk.txt",
                        "origin": "run"
                    }]
                });
                let manifest_path = dir.join("talk-hash.hippo.json");
                std::fs::write(&manifest_path, manifest.to_string()).unwrap();
                app.recent.push(RecentEntry {
                    audio: Some(audio),
                    transcript: Some(transcript),
                    manifest: Some(manifest_path.display().to_string()),
                    finished_at: 5,
                    ..Default::default()
                });
                let index = app.recent.len() - 1;
                app.open_versions(PaneTab::History, index);
            }
            Modal::Labels => {
                app.recent.push(RecentEntry {
                    audio: Some(PathBuf::from("/media/talk.mp3")),
                    transcript: Some(PathBuf::from("/media/talk.txt")),
                    finished_at: 5,
                    ..Default::default()
                });
                let index = app.recent.len() - 1;
                app.open_labels(PaneTab::History, index);
            }
            Modal::Report => app.report_open = true,
            Modal::RenameRecent => {
                app.recent.push(RecentEntry {
                    audio: Some(PathBuf::from("/media/talk.mp3")),
                    transcript: Some(PathBuf::from("/media/talk.txt")),
                    finished_at: 5,
                    ..Default::default()
                });
                let index = app.recent.len() - 1;
                app.rename_recent = Some(RenameRecent {
                    row: index,
                    text: "talk.mp3".to_string(),
                });
            }
        }
    }

