    #[test]
    fn exporting_a_briefing_offers_every_format_and_writes_key_points_only() {
        let _guard = env_lock();
        let _config = ConfigEnv::new("briefing-export");
        let media = temp_dir("briefing-export-media");
        let transcript = media.join("talk.txt");
        std::fs::write(&transcript, "[00:00] SPEAKER 1: hi\n").unwrap();

        let mut app = pro_app();
        app.briefing = Some(BriefingState::Ready {
            briefing: Briefing {
                overview: "A short talk.".to_string(),
                points: vec![hippo_briefing::Item {
                    text: "The sky is blue".to_string(),
                    lines: vec![1],
                }],
                decisions: vec![hippo_briefing::Item {
                    text: "Ship it".to_string(),
                    lines: vec![1],
                }],
                actions: vec![hippo_briefing::Item {
                    text: "Call Ada".to_string(),
                    lines: vec![1],
                }],
            },
            lines: vec![BriefingLine {
                start: 0.0,
                end: Some(2.0),
                speaker: "SPEAKER 1".to_string(),
                text: "hi".to_string(),
            }],
            source: Some(transcript.clone()),
        });

        let _ = app.update(Message::ToggleBriefingExport);
        assert!(app.briefing_export_open);
        // The open list renders inside the dialog.
        let _ = app.view();

        let _ = app.update(Message::ExportBriefing(ExportFormat::Txt));
        assert!(!app.briefing_export_open, "choosing a format closes the list");
        let pending = app
            .pending_export
            .as_ref()
            .expect("the export should be waiting on a destination");
        assert_eq!(pending.format, ExportFormat::Txt);
        assert_eq!(pending.suggested, media.join("talk-summary.txt"));
        assert!(pending.text.contains("Key points"));
        assert!(
            !pending.text.contains("Ship it") && !pending.text.contains("Call Ada"),
            "decisions and action items must not be listed: {}",
            pending.text
        );

        let chosen = media.join("notes.txt");
        let _ = app.update(Message::ExportPicked(Some(chosen.clone())));
        let written = std::fs::read_to_string(&chosen).unwrap();
        assert!(written.contains("The sky is blue"), "{written}");
        assert!(!written.contains("Ship it"), "{written}");

        // The timed formats time each key point by the line it cites.
        let _ = app.update(Message::ExportBriefing(ExportFormat::Srt));
        let srt = media.join("notes.srt");
        let _ = app.update(Message::ExportPicked(Some(srt.clone())));
        let written = std::fs::read_to_string(&srt).unwrap();
        assert!(
            written.contains("00:00:00,000 --> 00:00:02,000"),
            "{written}"
        );
        assert!(written.contains("The sky is blue"), "{written}");

        let _ = std::fs::remove_dir_all(&media);
    }

    #[test]
    fn generating_a_report_writes_the_chosen_sections_and_format() {
        let _guard = env_lock();
        let _config = ConfigEnv::new("report-export");
        let original = "[00:00] SPEAKER 1: hello there\n[00:03] SPEAKER 1: again\n[00:06] SPEAKER 2: bye\n";
        let (mut app, transcript, media) = line_edit_fixture("report-export", original);

        app.briefing = Some(BriefingState::Ready {
            briefing: Briefing {
                overview: "Short talk.".to_string(),
                points: vec![hippo_briefing::Item {
                    text: "The sky is blue".to_string(),
                    lines: vec![1],
                }],
                decisions: Vec::new(),
                actions: Vec::new(),
            },
            lines: vec![
                BriefingLine {
                    start: 0.0,
                    end: Some(3.0),
                    speaker: "SPEAKER 1".to_string(),
                    text: "hello there".to_string(),
                },
                BriefingLine {
                    start: 3.0,
                    end: Some(6.0),
                    speaker: "SPEAKER 1".to_string(),
                    text: "again".to_string(),
                },
                BriefingLine {
                    start: 6.0,
                    end: Some(9.0),
                    speaker: "SPEAKER 2".to_string(),
                    text: "bye".to_string(),
                },
            ],
            source: Some(transcript.clone()),
        });

        let _ = app.update(Message::OpenReport);
        assert!(app.report_open);
        assert!(
            app.report.summary,
            "a ready summary should be offered by default"
        );
        assert_eq!(app.report.format, ReportFormat::Pdf);

        // Merge consecutive turns and drop the timestamps.
        let _ = app.update(Message::ReportToggled(ReportToggle::MergeLines));
        let _ = app.update(Message::ReportToggled(ReportToggle::Timestamps));
        let _ = app.update(Message::ReportFormatChanged(ReportFormat::Txt));
        let _ = app.update(Message::SaveReport);
        assert!(!app.report_open);
        let report = app
            .pending_report
            .as_ref()
            .expect("the report waits on a destination");
        assert_eq!(report.format, ReportFormat::Txt);
        let blocks = report.blocks.clone();

        assert_eq!(blocks[0], ReportBlock::Title("talk.mp3".to_string()));
        assert!(matches!(
            blocks.get(1),
            Some(ReportBlock::Meta(text)) if text.starts_with("Generated ")
        ));
        assert!(blocks.contains(&ReportBlock::Heading("Participants".to_string())));
        assert!(
            blocks.iter().any(|block| matches!(
                block,
                ReportBlock::Bullet(text) if text.starts_with("SPEAKER 1 \u{2014} 0:06 speaking")
            )),
            "{blocks:?}"
        );
        assert!(
            blocks.contains(&ReportBlock::Paragraph(
                "SPEAKER 1: hello there again".to_string()
            )),
            "{blocks:?}"
        );
        assert!(blocks.contains(&ReportBlock::Paragraph("SPEAKER 2: bye".to_string())));
        assert!(blocks.contains(&ReportBlock::Heading("Summary".to_string())));
        assert!(blocks.iter().any(|block| matches!(
            block,
            ReportBlock::Bullet(text) if text.starts_with("The sky is blue")
        )));

        let chosen = media.join("report.txt");
        let _ = app.update(Message::ReportPicked(Some(chosen.clone())));
        let saved = std::fs::read_to_string(&chosen).unwrap();
        assert!(saved.contains("PARTICIPANTS"), "{saved}");
        assert!(saved.contains("SPEAKER 1: hello there again"), "{saved}");

        // Word output without the summary section.
        let _ = app.update(Message::OpenReport);
        let _ = app.update(Message::ReportToggled(ReportToggle::Summary));
        let _ = app.update(Message::ReportFormatChanged(ReportFormat::Docx));
        let _ = app.update(Message::SaveReport);
        let docx = media.join("report.docx");
        let _ = app.update(Message::ReportPicked(Some(docx.clone())));
        let bytes = std::fs::read(&docx).unwrap();
        assert_eq!(&bytes[..2], b"PK", "the report must be a docx package");

        let _ = std::fs::remove_dir_all(&media);
    }

    #[test]
    fn a_report_that_asks_for_a_summary_makes_one_first() {
        let _guard = env_lock();
        let _config = ConfigEnv::new("report-summary-chain");
        let original = "[00:00] SPEAKER 1: one\n[00:05] SPEAKER 2: two\n";
        let (mut app, transcript, media) = line_edit_fixture("report-summary-chain", original);

        assert!(app.briefing.is_none());
        let _ = app.update(Message::OpenReport);
        let _ = app.update(Message::ReportToggled(ReportToggle::Summary));
        assert!(app.report.summary);
        let _ = app.update(Message::SaveReport);

        // The summary comes first: nothing is written and the progress dialog
        // has the screen.
        assert!(app.pending_report.is_none());
        assert!(app.report_after_summary);
        assert!(app.briefing.is_some(), "the summary step should be showing");
        assert!(!app.report_open);

        // When it lands, the save prompt follows and the progress dialog closes.
        app.briefing = Some(BriefingState::Ready {
            briefing: Briefing {
                overview: "Short talk.".to_string(),
                points: vec![hippo_briefing::Item {
                    text: "The sky is blue".to_string(),
                    lines: vec![1],
                }],
                decisions: Vec::new(),
                actions: Vec::new(),
            },
            lines: vec![BriefingLine {
                start: 0.0,
                end: Some(2.0),
                speaker: "SPEAKER 1".to_string(),
                text: "one".to_string(),
            }],
            source: Some(transcript.clone()),
        });
        let _ = app.resume_report_after_summary();

        assert!(!app.report_after_summary);
        assert!(
            app.briefing.is_none(),
            "the progress dialog gives way to the save prompt"
        );
        let blocks = &app
            .pending_report
            .as_ref()
            .expect("the report should be waiting on its destination")
            .blocks;
        assert!(blocks.contains(&ReportBlock::Heading("Summary".to_string())));
        assert!(blocks.iter().any(|block| matches!(
            block,
            ReportBlock::Bullet(text) if text.starts_with("The sky is blue")
        )));

        let _ = std::fs::remove_dir_all(&media);
    }

